template <typename T> std::vector<int>Array1DSeek(T*data, T*succ, int succL, int curL, bool (*Equals)(const T& x1, const T& x2, int params)=EqualSimple, int FromN=1, int ToN=0, TValsShowHide*vsh=NULL){
    std::vector<int> Ns;
    int Q=succL-curL+1;
    TValsShowHide vsh1;
    if(vsh!=NULL)vsh1=*vsh;
    vsh1.EnableWriting();
    writeln(&vsh1, "Seek(1D in 1D) starts working");
    if(Q>0){
        if(ToN<1){
            ToN=Q;
        }
       if(FromN>ToN){
           FromN=ToN;
       }
       if(FromN<1){
           FromN=1;
       }
       writeln(&vsh1,"Length to seek in: "+IntToStr(Q)+" Length to seek: "+IntToStr(succL));
       for(int i=FromN; i<=ToN; i++){
           writeln(&vsh1,"PosNn: "+IntToStr(i)+"checking... ");
           if(Array1DSuccIsAtPos(data, succ, curL, i, succL, Equals, &vsh1)){
               Ns.push_back(i);
               writeln(&vsh1,"Found!");
           }else  writeln(&vsh1,"NOT found");
        }
    }
    writeln(&vsh1, "Seek(1D in 1D) finishes working");
    return Ns;
}

template<typename T>void Array1DConcatRow(T*&X1, int&L1, T*X2, int L2, T DfltValParam, int Lreq=0, int whatFromN=1, int QDefaultValsBefore=0){
    std::vector<T>X2fact=Array1DGetSubArray_byLs_PreMark(X2, L2, Lreq, whatFromN, QDefaultValsBefore, &DfltValParam);
    T val;
    int L2fact=X2fact.size();
    for(int i=1; i<=L2fact; i++){
        val=X2fact[i-1];
        Array1DAddElement(X1, L1, val);
    }
}
template<typename T>void Array1DConcatRow(T*&X1, int&L1, T*X2, int L2, T*DfltValParam=NULL, int Lreq=0, int whatFromN=1, int QDefaultValsBefore=0){
    std::vector<T>X2fact=Array1DGetSubArray_byLs_PreMark(X2, L2, Lreq, whatFromN, QDefaultValsBefore, DfltValParam);
    T val;
    int L2fact=X2fact.size();
    for(int i=1; i<=L2fact; i++){
        val=X2fact[i-1];
        Array1DAddElement(X1, L1, val);
    }
}

