  private:
    void Calc_Array1DSubArray_byLs_MarkupNs_vFmls(int&LreqCalcd, int&preN1_, int&preN2_, int&ownN1_, int&ownN2, int&ForOwnN1_, int&ForOwnN2, int&postN1, int&postN2_, int Lini){
        int LreqGiven=this->QReq, whatFromN=this->FromN, QDefaultValuesBefore=this->QDfltBefore;
        int LownMax;//, LreqGiven;
        if(whatFromN<0){
            whatFromN=Lini+whatFromN+1;
        }
        //DefaultValuesBefore
        if(QDefaultValuesBefore>0){
            preN1_=1;
            if(LreqGiven <= 1 || LreqGiven >= QDefaultValuesBefore){
                preN2_=QDefaultValuesBefore;
            }else{
                preN2_=LreqGiven;
            }
        }else{
            preN1_=0;
            preN2_=0;
        }
        //Own values
        if(whatFromN <= Lini && (LreqGiven <= 1 || (LreqGiven >= 1 && LreqGiven >= QDefaultValuesBefore))) {
            ownN1_=whatFromN;
            //ForOwnN1_ = preN2_+ownN1_;
            ForOwnN1_=preN2_+1;
            //ForOwnN2 wi def'd af
        }else{
            ownN1_=0;
            ownN2=0;
            ForOwnN1_=0;
            ForOwnN2=0;//tgo S ablb def'd nu
        }
        //Lown(Max), et, if D ns'def'd, ownN2 et ForOwnN2
        if(ownN1_>=1){
            LownMax=Lini-whatFromN+1;
            if(LreqGiven <= 1 || LreqGiven >= QDefaultValuesBefore + LownMax){//unlimited
                ownN2=Lini;
                ForOwnN2 = ForOwnN1_ + LownMax - 1;//corr'd
            }else{//limited
                ForOwnN2=LreqGiven;
                ownN2=ownN1_+(ForOwnN2-ForOwnN1_+1)-1;//vikts! fml qvi'dd!
            }
        }else{
            LownMax=0;
        }
        //LreqCalcd
        //if(LreqGiven<=0){
        //    LreqCalcd=QDefaultValuesBefore+LownMax;//LownMax==0 if whatFromN>Lini
        //}else if(LreqGiven>=)
        //post
        if(ForOwnN2>0 && ForOwnN2<LreqGiven){
            postN1=ForOwnN2+1;
            postN2_=LreqGiven;
        }else{
            postN1=0;
            postN2_=0;
        }
        //LreqCalcd
        if(LreqGiven>0){
            LreqCalcd=LreqGiven;
        }else{
             LreqCalcd=QDefaultValuesBefore+LownMax;//LownMax==0 if whatFromN>Lini
        }
    }//fn
