class TListOfNumberPairs{
  public:
    std::vector<Int2DVectorOfSizeOrCoords>data;
    //
    TListOfNumberPairs(){}
    ~TListOfNumberPairs(){}
    //
    void SetNull(){ data.clear(); }
    void DelN(int N){ Array1DDelElementFromN(data, N); }
    void Add(int de1, int di2){
        Int2DVectorOfSizeOrCoords pair;
        pair.d1=de1;
        pair.d2=di2;
        Array1DAddElement(data, pair);
    }
    void InsToN(int N, int de1, int di2){
        Int2DVectorOfSizeOrCoords pair;
        pair.d1=de1;
        pair.d2=di2;
        Array1DInsElementToN(data, N, pair);
    }
    int GetD1N(int N){
        int y=0;
        Int2DVectorOfSizeOrCoords pair;
        if(N>=1 && N<=data.size()){
            pair=data[N-1];
            y=pair.d1;
        }
        return y;
    }
    int GetD2N(int N){
        int y=0;
        Int2DVectorOfSizeOrCoords pair;
        if(N>=1 && N<=data.size()){
            pair=data[N-1];
            y=pair.d2;
        }
        return y;
    }
    void SetD1N(int d1, int N){
        Int2DVectorOfSizeOrCoords pair;
        if(N>=1 && N<=data.size()){
            pair=data[N-1];
            pair.d1=d1;
            data[N-1]=pair;
        }
    }
    void SetD2N(int d2, int N){
        Int2DVectorOfSizeOrCoords pair;
        if(N>=1 && N<=data.size()){
            pair=data[N-1];
            pair.d2=d2;
            data[N-1]=pair;
        }
    }
};

