template <typename T>std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x, int rowL, T DefaultValue, TDataShiftParams*DataShiftParam=NULL){
    std::vector<T>dfltRow;
    //int LDfltMax=rowL+Lreq;
    TDataShiftParams DataShift;
    T CurOwnVal;
    int PreN2, ownN1, ownN2, PostN1, PostN2;
    if(DataShiftParam!=NULL){
        DataShift=(*(DataShiftParam));
    }
    //Pre
    //if(DataShift.FromN>0){
    //    LDfltMax+=(DataShift.FromN;
    //}
    //if(DataShift.QDfltBefore>0){
    //    LDfltMax+=DataShift.QDfltBefore;
    //}
    //for(int i=1; i<=LDfltMax; i++){
    //    dfltRow.push_back(DefaultValue);
    //}
    PreN2=DataShift.GetPreN2(rowL);
    if(PreN2>0){
        for(int i=1; i<=PreN2; i++){
            dfltRow.push_back(DefaultValue);
        }
    }
    //Own
    ownN1=DataShift.GetOwnN1Own(rowL);
    ownN2=DataShift.GetOwnN1Own(rowL);
    if(ownN2>0){
        for(int i=ownN1; i<=ownN2; i++){
            CurOwnVal=x[i-1];
            dfltRow.push_back(CurOwnVal);
        }
    }
    //Post
    PostN1=DataShift.GetPostN1(rowL);
    PostN2=DataShift.GetPostN2(rowL);
    if(PostN2>0){
        for(int i=PostN1; i<=PostN2; i++){
            dfltRow.push_back(DefaultValue);
        }
    }
    return  dfltRow;
}

template <typename T>std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x, int rowL, T*DefaultValParam=NULL, TDataShiftParams*DataShiftParam=NULL){
   T DefaultValue;
   if(*DefaultValParam!=NULL){
       DefaultValue=(*(DefaultValParam));
   }
   //std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x, int Lold, T DefaultValue, TDataShiftParams*DataShiftParam=NULL){
   return           Array1DGetSubArray_byLs_PreMark_v2(  x,     rowL,   DefaultValue,  DataShiftParam);
}

template <typename T>std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x, int rowL, T*x2, int L2, T DefaultVal, TDataShiftParams*DataShiftParam=NULL){
    std::vector<T> row;
    int minL;
    int PreN2, ownN1, ownN2, PostN1, PostN2;
    TDataShiftParams DataShift;
    T val;
    if(DataShiftParam!=NULL){
        DataShift=(*(DataShiftParam));
    }
    //Pre
    PreN2=DataShift.GetPreN2(rowL);
    if(PreN2>0){
        minL = PreN2 <= L2 ? PreN2 : L2;
        for(int i=1; i<=minL; i++){
            val=x2[i-1];
            row.push_back(val);
        }
        for(int i=minL+1; i<=PreN2; i++){
            row.push_back(DefaultVal);
        }
    }
    //own
    ownN1=DataShift.GetOwnN1Own(rowL);
    ownN2=DataShift.GetOwnN2Own(rowL);
    if(ownN2>0){
        for(int i=ownN1; i<=ownN2; i++){
            val=x[i-1];
            row.push_back(val);
        }
    }
    //Post
    PostN1=DataShift.GetPostN1(rowL);
    PostN2=DataShift.GetPostN2(rowL);
    if(PostN2>0){
        if(L2<PostN1){
            for(int i=PostN1; i<=PostN2; i++){
                row.push_back(DefaultVal);
            }
        }else{
            minL = L2 <= PostN2 ? L2 : PostN2;
            for(int i=PostN1; i<=minL; i++){
                val=x2[i-1];
                row.push_back(val);
            }
            for(int i=minL+1; i<=PostN2; i++){
                row.push_back(DefaultVal);
            }
        }
    }
    return row;
}

