        Calc_Array1DSubArray_byLs_MarkupNs_vFmls( LreqCalcd,     preN1_,    preN2_,     ownN1_,     ownN2,      ForOwnN1_,    ForOwnN2,      postN1,     postN2_, wholeRowL,       LreqGiven,       whatFromN,       QDefaultValuesBefore);
        //pre part
