template<typename T> void ArrayOf2DBy1D_SetElement_AsVal(T*&X, const Array2DSize&size, const T& val, int ExtRowN, int IneRowN){
    int QExtRows=size.GetQExtRows(), curL, PosN;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        curL=size.GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN<=curL){
            PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
            X[PosN-1]=val;
        }
    }
}
template<typename T> void ArrayOf2DBy1D_SetElement_AsVal(std::vector<T>&X, const Array2DSize&size, const T& val, int ExtRowN, int IneRowN){
    int QExtRows=size.GetQExtRows(), curL, PosN;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        curL=size.GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN<=curL){
            PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
            X[PosN-1]=val;
        }
    }
}

template<typename T> T ArrayOf2DBy1D_GetElement_AsVal(T*X, const Array2DSize&size, int ExtRowN, int IneRowN){
    T val;
    int QExtRows=size.GetQExtRows(), curL, PosN;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        curL=size.GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN<=curL){
            PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
            val=X[PosN-1];
        }
    }
    return val;
}
