template<typename T> std::vector<T> ArrayOf2DBy1D_GetIneRowN_AsStdVector_v2(T*X, const Array2DSize&size, int IneRowN, T DefaultVal, int IRL_QER0_IRL_All_NsAs_AllExtRows1_LongEnoughExtRows2_FromStartToBreak3=0){
    std::vector<T>row;
    T val;
    int QER=size.GetQExtRows(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(), IRL_all=size.LengthFullFormalOfIneRowN(IneRowN), IRL_StartBreak=size.LengthFactOfIneRowN_From1stToFirstStop(IneRowN), curL, Lgiven1, Lreq0, Lreq1, Lreq2, count=0;
    int preN1_, preN2_, ownN1_, ownN2, ForOwnN1_, ForOwnN2, postN1, postN2_;
    std::vector<int>NsLGE=size.GetNsOfExtRowsWhoseLengthIsGE(IneRowN);
    bool specCase=false;
    if(IneRowN<0){
        IneRowN-=(Lmax+1);
    }
    if(IneRowN>=1 && IneRowN<=Lmax){
        if(IneRowN<=Lmin){
            for(int i=1; i<=QER; i++){
                val=ArrayOf2DBy1D_GetElement_AsVal(X, size, i, IneRowN);
                row.push_back(val);
            }
        }else{
            switch(IRL_QER0_IRL_All_NsAs_AllExtRows1_LongEnoughExtRows2_FromStartToBreak3){
                case 0:
                    for(int i=1; i<=QER; i++){
                        curL=size.GetLength(i);
                        if(curL>=IneRowN){
                            val=ArrayOf2DBy1D_GetElement_AsVal(X, size, i, IneRowN);
                            row.push_back(val);
                        }else{
                            row.push_back(DefaultVal);
                        }
                    }
                break;
                case 1://IRL_All_NsAs_AllExtRows1
                    count=0;
                    for(int i=1; i<=QER; i++){
                        curL=size.GetLength(i);
                        if(curL>=IneRowN){
                            count++;
                            val=ArrayOf2DBy1D_GetElement_AsVal(X, size, i, IneRowN);
                            row.push_back(val);
                        }else{
                            row.push_back(DefaultVal);
                        }
                        if(count>=NsLGE[NsLGE.size()-1]){
                            break;
                        }
                    }
                break;
                case 2://IRL_All_NsAs__LongEnoughExtRows2
                    for(int i=1; i<=QER; i++){
                        curL=size.GetLength(i);
                        if(curL>=IneRowN){
                            val=ArrayOf2DBy1D_GetElement_AsVal(X, size, i, IneRowN);
                            row.push_back(val);
                        }
                    }
                break;
                case 3:
                    if(IRL_StartBreak>0){
                        for(int i=1; i<=IRL_StartBreak; i++){//0 or >
                            val=ArrayOf2DBy1D_GetElement_AsVal(X, size, i, IneRowN);
                            row.push_back(val);
                        }
                    }//else{
                    //    for(int i=1; i<=QER; i++){
                    //        row.push_back(DefaultVal);
                    //    }
                    //}
                break;
            }//sw
        }
    }//if Lmax
    return row;
}//fn get ine v2
