    return ArrayOf2DBy1D_GetIneRowN_AsStdVector_v2( X,                   size,     IneRowN,   DefaultVal,      IRL_QER0_IRL_All_NsAs_AllExtRows1_LongEnoughExtRows2_FromStartToBreak3);
