template<typename T> std::vector<T> ArrayOf2DBy1D_GetIneRowN_AsStdVector(T*X, const Array2DSize&size, int IneRowN, int  IfBetweenMinAndMax_Empty0UpToFirstNotWithin1AllWhichAreWithin2DefaultValIfNotWithin3=1, T*DfltValParam=NULL){
    std::vector<T> Row;
    T curVal, defaultVal;
    bool contin;
    int QExtRows=size.GetQExtRows(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(), L1=size.GetMaxLength(), L, PosN, N;
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(DfltValParam!=NULL){
        defaultVal=(*(DfltValParam));
    }
    switch(IfBetweenMinAndMax_Empty0UpToFirstNotWithin1AllWhichAreWithin2DefaultValIfNotWithin3){
        case 1:
            if(IneRowN>=1 && IneRowN<=L1){
                contin=(IneRowN<=L1);
                N=0;
                while(contin){
                    N++;
                    L=size.GetLength(N);
                    if(IneRowN>L){
                        contin=false;
                    }else{
                        //PosN=size.GetPositionByCoordsIfRealizedAs1D(1, IneRowN);
                        //curVal=X[PosN-1];
                        curVal=ArrayOf2DBy1D_GetElement_AsVal(X, size, N, IneRowN);
                        Row.push_back(curVal);
                    }
                }
            }
        break;
        case 2:
            if(IneRowN>=1 && IneRowN<=Lmax){
                for(N=1; N<=QExtRows; N++){
                    L=size.GetLength(N);
                    if(IneRowN<=L){
                        //PosN=size.GetPositionByCoordsIfRealizedAs1D(N, IneRowN);
                        curVal=ArrayOf2DBy1D_GetElement_AsVal(X, size, N, IneRowN);
                        //curVal=X[PosN-1];
                        Row.push_back(curVal);
                    }
                }
            }
        break;
        case 2:
            if(IneRowN>=1 && IneRowN<=Lmax){
                for(N=1; N<=QExtRows; N++){
                    L=size.GetLength(N);
                    if(IneRowN>L){
                        Row.push_back(defaultVal);
                    }else{
                        //PosN=size.GetPositionByCoordsIfRealizedAs1D(N, IneRowN);
                        //curVal=X[PosN-1];
                        curVal=ArrayOf2DBy1D_GetElement_AsVal(X, size, N, IneRowN);
                        Row.push_back(curVal);
                    }
                }
            }
        break;
        default://0
            if(IneRowN>=1 && IneRowN<=Lmin){
                for(N=1; N<=QExtRows; N++){
                    //PosN=size.GetPositionByCoordsIfRealizedAs1D(N, IneRowN);
                    //curVal=X[PosN-1];
                    curVal=ArrayOf2DBy1D_GetElement_AsVal(X, size, N, IneRowN);
                    Row.push_back(curVal);
                }
            }
        break;
    }
    return Row;
}

