template<typename T> void ArrayOf2DBy1D_SetLengthOfExtRowN(T*&X, Array2DSize&size, int ExtRowN, int newL, T DfltValParam){
    int QExtRows=size.GetQExtRows(), oldL, PosN, QElts;
    T dfltVal=DfltValParam;
    if(ExtRowN<0){
        ExtRowN-=(QExtRows+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        oldL=size.GetLength(ExtRowN);
        PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        QElts=size.GetQElements();
        if(oldL<newL){
            for(int i=1; i<=(newL-oldL); i++){
                Array1DInsElementToN(X, QElts, PosN+oldL, dfltVal);
            }
        }else if(oldL>newL){
            for(int i=1; i<=(oldL-newL); i++){
                Array1DDelElementFromN(X, QElts, PosN+newL);
            }
        }
    }//else = => NOp
}

