template<typename T>ArrayOf2DBy1DReverseExtRows(T*&X, Array2DSize& size){
    int Q=size.GetQExtRows(), N1, N2, Nmid;
    if(Q%2==0){
        Nmid=Q/2;
    }else{
        Nmid=(Q-1)/2;
    }
    for(N1=1; N1<=Nmid; N1++){
        N2=Q-N1+1;
        ArrayOf2DBy1D_SwapExtRows(X, size, N1, N2);
    }
}
template<typename T>ArrayOf2DBy1DReverseExtRows(std::vector<T>&X, const Array2DSize& size){
    //int Q=size.GetQExtRows(), L1, L2, Lmin=size.GetMinLength(), Lmax=size.GetMaxLength();
    int Q=size.GetQExtRows(), N1, N2, Nmid;
    if(Q%2==0){
        Nmid=Q/2;
    }else{
        Nmid=(Q-1)/2;
    }
    for(N1=1; N1<Nmid; N1++){
        N2=Q-N1+1;
        ArrayOf2DBy1D_SwapExtRows(X, size, N1, N2);
    }
}
