//ReverseExtRowN
template<typename T>ArrayOf2DBy1D_ReverseExtRowN(T*&X, const Array2DSize& size, int ExtRowN){
    int Lcur;
    std::vector<T>row;
    if(ExtRowN>=1 && ExtRowN<=size.GetQExtRows()){
        Lcur=size.GetLength(ExtRowN);
        row=ArrayOf2DBy1D_GetExtRowN_AsStdVector(X, size, ExtRowN);
        Array1DReverse(row);
        ArrayOf2DBy1D_SetExtRowN(X, size, ExtRowN, row.data(), row.size());
    }
}
template<typename T>ArrayOf2DBy1D_ReverseExtRowN(std::vector<T>&X, const Array2DSize& size, int ExtRowN){
    std::vector<T>row;
    int Lcur, PosEdge1, PosEdge2, NMed, PosMed, N1, N2, PosN1, PosN2, QElts=size.GetQElements();
    if(ExtRowN>=1 && ExtRowN<=size.GetQExtRows()){
        Lcur=size.GetLength(ExtRowN);
        PosEdge1=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        PosEdge2=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, Lcur);
        if(Lcur%2==0){
            NMed=Lcur/2;
        }else{
            NMed=(Lcur-1)/2;
        }
        PosMed=PosEdge1-1+NMed;
        for(N1=1; N1<=NMed; N1++){
            N2=Lcur-N1+1;
            PosN1=PosEdge1-1+N1;
            PosN2=PosEdge1-1+N2;
            Array1DSwapElements(X, PosN1, PosN2);
        }
        //row=ArrayOf2DBy1D_GetExtRowN_AsStdVector(X, size, ExtRowN);
        //Array1DReverse(row);
        //ArrayOf2DBy1D_SetExtRowN(X, size, ExtRowN, row);
    }
}
