template<typename T>ArrayOf2DBy1D_AddToExtRowN(T*&X, Array2DSize& size, int ExtRowN, T val){
    int QExtRows=size.GetQExtRows(), QElts=size.GetQElements(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(), Lcur, PosN;
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        Lcur=size.GetLength(ExtRowN);
        PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, Lcur);
        if(ExtRowN<QExtRows){
            Array1DAddElement(X, QElts, val);
        }else{
            Array1DInsElementToN(X, QElts, PosN, val);
        }
        size.SetLength(Lcur+1,ExtRowN );
    }
}
