template<typename T>ArrayOf2DBy1D_DelExtRowN(T*&X, Array2DSize& size, int ExtRowN){
    int QER=size.GetQExtRows(), PosN, QElts=size.GetQElements(), L;
    if(ExtRowN>=1 && ExtRowN<=QER){
        L=size.GetLength(ExtRowN);
        PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        for(int i=1; i<=L; i++){
            Array1DDelElementFromN(X, QElts, PosN);
        }
        size.DelExt(ExtRowN);
    }
}
template<typename T>ArrayOf2DBy1D_DelExtRowN(std::vector<T>&X, Array2DSize& size, int ExtRowN){
    int QER=size.GetQExtRows(), PosN, QElts=size.GetQElements(), L;
    if(ExtRowN>=1 && ExtRowN<=QER){
        L=size.GetLength(ExtRowN);
        PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        for(int i=1; i<=L; i++){
            //Array1DDelElementFromN(X, QElts, PosN);
            Array1DDelElementFromN(X, PosN);
        }
        size.DelExt(ExtRowN);
    }
}
