template<typename T>bool ArrayOf2DBy1D_ValIsAtPos(T*X, const Array2DSize&size, const T& valExt, int ExtRowN=1, int IneRowN=1){
    bool verdict=false;
    int PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
    T valIne;
    if(PosN==0){
        verdict=false;
    }else{
        valIne=X[PosN-1];
        verdict=(valIne==valExt);
    }
    return verdict;
}
