template<typename T>bool ArrayOf2DBy1D_ExtSubRowIsAtPos_Simply(T*X, const Array2DSize&size, T*row, int L, int ExtRowN=1, int IneRowN=1, bool SoughtNotReversed=true){
    int QExtRows=size.GetQExtRows(), Lmax=size.GetMaxLength(), Lcur, PosN;
    //std::vector<T>rowWhere, rowWhat;
    T valExt, valIne;
    bool b=false;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        Lcur=size.GetLength(ExtRowN);
        if(SoughtNotReversed){
            if(IneRowN>=1 && IneRowN+L-1<=Lcur){
                b=true;
                for(int i=1; i<=L; i++){
                    valExt=row[i-1];
                    PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN+i-1);
                    valIne=X[PosN-1];
                    if(!(valExt==valIne)){
                        b=false;
                    }
                }
            }
        }else{//reversed
            if(IneRowN-L+1>=1 && IneRowN<=Lcur){
                b=true;
                for(int i=1; i<=L; i++){
                    valExt=row[i-1];
                    PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN-i+1);
                    valIne=X[PosN-1];
                    if(!(valExt==valIne)){
                        b=false;
                    }
                }
            }
        }
    }
    return b;
}
