template <typename T> ArrayOf2DBy1D_ValSetOrAddOrFillOrIgnore(T*&X, Array2DSize& size, T val, int ExtRowN, int IneRowN, T DefaultVal, bool SetRect=true, int DfltRowL_00_11_Max2_Min3=2){
    int QExtRows=size.GetQExtRows(), Lmax=size.GetMaxLength(), Lmin=size.GetMinLength(),  Lcur;
    std::vector<T>row;
    Array2DSize size1;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(ExtRowN==0){
       for(int i=1; i<=QExtRows; i++){
           Lcur=size.GetLength(i);
           for(int j=1; j<=Lcur; j++){
               ArrayOf2DBy1D_SetElement_AsVal(X, size, val, i, j);
           }
       }
    }else if(ExtRowN==QExtRows+1){
        //Add
        switch(DfltRowL_00_11_Max2_Min3){
            case 0:
            case 1:
                Lcur=DfltRowL_00_11_Max2_Min3;
            break;
            case 2:
                Lcur=Lmax;
            break;
            case 3:
                Lcur=Lmin;
            break;
        }
        for(int i=1; i<=Lcur; i++){
            row.push_back(DefaultVal);
        }
        if(IneRowN==0){
            //fill
            for(int i=1; i<=Lcur; i++){
                 row[i-1]=val;
             }
        }else if(IneRowN>0){
            if(IneRowN>=1 && IneRowN<=Lcur){
                //set
                row[IneRowN-1]=val;
            }else if(IneRowN>Lcur){
                //add
                for(int i=Lcur+1; i<=IneRowN; i++){
                    row.push_back(DefaultVal);
               }
            }
            row[IneRowN-1]=val;
            ArrayOf2DBy1D_AddExtRow(X, size, row);
        }//else NOp;
    }else if(ExtRowN>=1 && ExtRowN<=QExtRows){
        //Set or Add
        Lcur=size.GetLength(ExtRowN);
        if(IneRowN==0){
            //fill
            for(int i=1; i<=Lcur; i++){
                 ArrayOf2DBy1D_SetElement_AsVal(X, size, val, ExtRowN, i);
            }
        }else if(IneRowN==Lcur+1){
            //Add to existing row
            ArrayOf2DBy1D_AddToExtRowN(X, size, ExtRowN, val);
        }else if(IneRowN>=1 && IneRowN<=Lcur){
            ArrayOf2DBy1D_SetElement_AsVal(X, size, val, ExtRowN, IneRowN);
        }//else NOP;
    }//else NOp;
    //Array2DSize size1;
    Lmin=size.GetMinLength();
    Lmax=size.GetMaxLength();
    QExtRows=size.GetQExtRows();
    if(Lmin!=Lmax && SetRect==true){
        ArrayOf2DBy1D_SetSize(X, size, QExtRows, Lmax, &DefaultVal);
    }
}//ArrayOf2DBy1D_ValSetOrAddOrFillOrIgnore
