template <typename T>void ArrayOf2DBy1D_StdCOut(T*X, const Array2DSize&size, QString delimElem="; ", QString delimLines="; ", bool useBrackets=true, bool Show2DNot1D=true, bool ByExtNotIneRows=true){
    int Q=size.GetQExtRows(), Lmax=size.GetMaxLength(), PosN, L;
    //template <typename T>void ArrayOf2DBy1DStdCOutSingleExtRow(T*X, const Array2DSize&size, int rowN, QString delimElem="; ", bool useBrackets=true){
    if(ByExtNotIneRows){
        if(useBrackets)std::cout<<"[";
        ArrayOf2DBy1D_StdCOutSingleExtRow(X, size, 1, delimElem, useBrackets);
        std::cout<<delimLines.toStdString().c_str();
        if(Show2DNot1D)std::cout<<std::endl;
        for(int i=2; i<=Q-1; i++){
            if(useBrackets)std::cout<<" ";
            ArrayOf2DBy1D_StdCOutSingleExtRow(X, size, i, delimElem, useBrackets);
            std::cout<<delimLines.toStdString().c_str();
            if(Show2DNot1D)std::cout<<std::endl;
        }
        if(useBrackets)std::cout<<" ";
        ArrayOf2DBy1D_StdCOutSingleExtRow(X, size, Q, delimElem, useBrackets);
        std::cout<<delimLines.toStdString().c_str();
        if(useBrackets)std::cout<<"]";
        if(Show2DNot1D)std::cout<<std::endl;
    }else if(size.IsForTranspose()){
        if(useBrackets)std::cout<<"[";
        ArrayOf2DBy1D_StdCOutSingleIneRow(X, size, 1, delimElem, useBrackets);
        std::cout<<delimLines.toStdString().c_str();
        if(Show2DNot1D)std::cout<<std::endl;
        for(int i=2; i<=Lmax-1; i++){
            if(useBrackets)std::cout<<" ";
            ArrayOf2DBy1D_StdCOutSingleIneRow(X, size, i, delimElem, useBrackets);
            std::cout<<delimLines.toStdString().c_str();
            if(Show2DNot1D)std::cout<<std::endl;
        }
        if(useBrackets)std::cout<<" ";
        ArrayOf2DBy1D_StdCOutSingleIneRow(X, size, Lmax, delimElem, useBrackets);
        std::cout<<delimLines.toStdString().c_str();
        if(useBrackets)std::cout<<"]";
        if(Show2DNot1D)std::cout<<std::endl;
    }
}

