//SetSize
template<typename T> void ArrayOf2Dv1_SetSize(T**&X, Array2DSize&size1, const Array2DSize&size2, T DefaultVal, bool PreserveVals=true){
    int L1, L2, QER1=size1.GetQExtRows(), QER2=size2.GetQExtRows(), Qmin=QER1<=QER2 ? QER1 : QER2, curQ;//, QEl1=size1.GetQElements(), curL, PosN;
    //T DefaultVal=DfltValParam;
    //if(DfltValParam!=NULL){
    //    DefaultVal=(*(DfltValParam));
    //}
    T*row=NULL;
    if(QER1>0){
        if(QER2>0){
            for(int i=1; i<=Qmin; i++){//resizing rows
                L1=size1.GetLength(i);
                L2=size2.GetLength(i);
                if(L2!=L1){
                    ArrayOf2Dv1_SetLengthOfExtRowN(X, size1, i, L2, DefaultVal);
                }
            }
            if(QER2>QER1){//adding rows
                curQ=QER1;
                for(int i=Qmin+1; i<=QER2; i++){
                    L2=size2.GetLength(i);
                    row=new T[DefaultVal];
                    for(int j=1; j<=L2; j++){
                        row[j-1]=DefaultVal;
                    }
                    Array1DAddElement(X, QER1, row);
                    if(row!=NULL){
                        delete[]row;
                        row=NULL;
                    }
                    size1.AddExt(L2);
                }
            }else if(QER2<QER1){//deleting rows
                //PosN=size1.GetPositionByCoordsIfRealizedAs1D(QER1, size1.GetLength(QER1))+1;
                //for(int i=Qmin+1; i<=QER2; i++){
                for(int i=QER2; i>=Qmin+1; i--){//ab fin ad ini
                    L1=size1.GetLength(i);
                    if(X[i-1]!=NULL){
                        delete[]X[i-1];
                        X[i-1]=NULL;
                    }
                    for(int j=1; j<=L1; j++){
                        Array1DDelElementFromN(X, QER1, i);
                    }
                    size1.DelExt(i);
                }
            }
        }else{
            delete[]X;
            X=NULL;
        }
    }
    size1=size2;
}
template<typename T> void ArrayOf2Dv1_SetSize(T**&X, Array2DSize&size1, const Array2DSize&size2, T*DfltValParam=NULL, bool PreserveVals=true){
    T DefaultVal;
    if(DfltValParam!=NULL){
        DefaultVal=(*(DfltValParam));
    }
    ArrayOf2Dv1_SetSize(X, size1, size2, DefaultVal, PreserveVals);
}
