//Set Ext Row N
//template<typename T> void ArrayOf2Dv1_SetExtRowN(T**&X, Array2DSize&size, int ExtRowN, T DefaultVal, T*rowParam, int wholeRowL=0, TDataShiftParams*DataShiftParam=NULL, bool KeepIfRect=true, bool DefaultIsSpecNotOwn=true, int SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6=2){
template<typename T> void ArrayOf2Dv1_SetExtRowN(T**&X, Array2DSize&size, int ExtRowN, T DefaultVal, T*rowParam, int wholeRowL=0, TDataShiftParams*DataShiftParam=NULL,  bool DefaultIsSpecNotOwn=true, int SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6=2){
    std::vector<T>rowFact, extRowWas;
    int QER=size.GetQExtRows(), preN2=0, ownN1, ownN2, postN1=0, postN2=0, PosN, minL, oldL, newL, maxL;
    int Lmax=size.GetMaxLength(), Lmin=size.GetMinLength();
    TDataShiftParams DataShift;
    Array2DSize sizeNew=size, sizeOld=size;
    T val;
    bool isRectEvenByStr=size.isRectangularEvenByStr();
    if(DataShiftParam!=NULL){
        DataShift=(*(DataShiftParam));
    }
    if(ExtRowN<0){
        ExtRowN+=(QER+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QER){
        if(wholeRowL==0){
            wholeRowL=size.GetLength(ExtRowN);
        }
        extRowWas=ArrayOf2Dv1_GetExtRowN_AsStdVector(X, size, ExtRowN);
        rowFact=Array1DGetSubArray_byLs_PreMark_v2(rowParam, wholeRowL, DefaultVal, DataShiftParam);
        newL=rowFact.size();
        rowFact.clear();
        //newL=wholeRowL;
        oldL=size.GetLength(ExtRowN);
        maxL = newL >= oldL ? newL : oldL;
        switch(SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6){
            case 3:
                DataShift.QReq=maxL;
            break;
            case 4:
                DataShift.QReq=Lmax;
            break;
            case 5:
                DataShift.QReq=oldL;
            break;
            case 6:
                DataShift.QReq=0;// ab ce calc newL
            break;
        }//switch//other cases: DataShift.QReq s'gi'd spec val et ms'b SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6==0 or 2
        if(DefaultIsSpecNotOwn){
            //template <typename T>std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x,      int rowL, T DefaultValue, TDataShiftParams*DataShiftParam=NULL){
            rowFact=                              Array1DGetSubArray_byLs_PreMark_v2(rowParam, wholeRowL,  DefaultVal,                DataShiftParam);
        }else{
            //template <typename T>std::vector<T> Array1DGetSubArray_byLs_PreMark_v2(T*x,      int rowL,             T*x2,           int L2, T DefaultVal, TDataShiftParams*DataShiftParam=NULL){
            rowFact=                              Array1DGetSubArray_byLs_PreMark_v2(rowParam, wholeRowL, extRowWas.data(),extRowWas.size(),   DefaultVal,                  DataShiftParam);
        }
        newL=rowFact.size();
        if(newL!=DataShift.QReq && DataShift.QReq!=0){
            //Error!
        }
        //2 Setting et Writing Size
        if(newL==oldL){
            if(sizeOld.isRectangularEvenByStr() && SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6==1){
                size.SetVaria(QER, newL);
            }
            //cases 2 et 0 s'here - NOP: if wa rect so wi rect, if ne wa so ne wa
        }else{
            //if Ls atals, S wi ne rect or abls fy S rect, mut'n l'Ls o'afq ext rows
            switch(SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6){
                case 0:
                case 1:
                case 2:
                    size.SetLength(newL, ExtRowN);
                break;
                case 3:
                case 4:
                case 5:
                case 6:
                    //sizeNew.SetLength(newL, ExtRowN);
                    sizeNew.Set(QER, newL);//fy all ext rows L=L(rowFact)
                    ArrayOf2Dv1_SetSize(X, size, sizeNew, DefaultVal);
                    //size.Set(QER, newL);
                    size=sizeNew;
                break;
            }
        }
        //Writing new row
        for(int i=1; i<=newL; i++){
            val=rowFact[i-1];
            ArrayOf2Dv1_SetElement_AsVal(X, size, val, ExtRowN, i);
        }
    }//if to do
}//fn set ext row
