template<typename T> void ArrayOf2Dv1_SwapVals(T**&X, const Array2DSize& size, int ExtRowN1, int IneRowN1, int ExtRowN2, int IneRowN2){
    int Q=size.GetQExtRows(), L1, L2, Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(),
        PosN1=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN1, IneRowN1),//hin wa err no match'n fn - ce wa ob in fn descr n'wa const, et hin size s'const
        PosN2=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN2, IneRowN2);
    T val;
    if(ExtRowN1<0){
        ExtRowN1=Q+ExtRowN1+1;
    }
    if(ExtRowN2<0){
        ExtRowN2=Q+ExtRowN2+1;
    }
    if(ExtRowN1>=1 && ExtRowN1<=Q && ExtRowN2>=1 && ExtRowN2<=Q){
        val=X[ExtRowN1-1][IneRowN1-1];
        X[ExtRowN1-1][IneRowN1-1]= X[ExtRowN2-1][IneRowN2-1];
        X[ExtRowN2-1][IneRowN2-1]=val;
    }
}
template<typename T> void ArrayOf2Dv1_SwapVals(std::vector<T>&X,  int ExtRowN1, int IneRowN1, int ExtRowN2, int IneRowN2){
    Array2DSize size=GetSizeOf2DVector(X);
    T val;
    int Q=size.GetQExtRows(), L1, L2, Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(),
        PosN1=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN1, IneRowN1),
        PosN2=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN2, IneRowN2);
    if(ExtRowN1<0){
        ExtRowN1=Q+ExtRowN1+1;
    }
    if(ExtRowN2<0){
        ExtRowN2=Q+ExtRowN2+1;
    }
    if(ExtRowN1>=1 && ExtRowN1<=Q && ExtRowN2>=1 && ExtRowN2<=Q){
        val=X[ExtRowN1-1][IneRowN1-1];
        X[ExtRowN1-1][IneRowN1-1]= X[ExtRowN2-1][IneRowN2-1];
        X[ExtRowN2-1][IneRowN2-1]=val;
    }
}
