template<typename T>ArrayOf2Dv1_SwapIneRows(T**&X, const Array2DSize& size, int IneRowN1, int IneRowN2){
    int Q=size.GetQExtRows(), L1, L2, Lmin, Lmax;
    if(Q>0){
        Lmin=size.GetMinLength();
        Lmax=size.GetMaxLength();
        if(IneRowN1<0){
            IneRowN1=Lmax+IneRowN1+1;
        }
        if(IneRowN2<0){
            IneRowN2=Lmax+IneRowN2+1;
        }
        if(IneRowN1>=1 && IneRowN1<=Lmin && IneRowN2>=1 && IneRowN2<=Lmin){
            for(int i=1; i<=Q; i++){
                ArrayOf2Dv1_SwapVals(X, size, i, IneRowN1, i, IneRowN2);
            }
        }
    }
}
