template<typename T>ArrayOf2Dv1_ReverseIneRows(T*&X, const Array2DSize& size){
    int Q=size.GetQExtRows(), N1, N2, Nmid, Lmax=size.GetMaxLength(), Lmin=size.GetMinLength();
    if(Lmin==Lmax){
        if(Lmax%2==0){
            Nmid=Q/2;
        }else{
            Nmid=(Lmax-1)/2;
        }
        for(N1=1; N1<Nmid; N1++){
            N2=Lmax-N1+1;
            for(int j=1; j<=Q; j++){
                ArrayOf2Dv1SwapVals(X, size, j, N1, j, N2);
            }
        }
    }
}
