template<typename T>ArrayOf2Dv1(T**&X, const Array2DSize& size, int IneRowN){
    int Q=size.GetQExtRows(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(), Nmid, N1, N2, IRL_Fact;
    if(IneRowN<0){
        IneRowN+=Lmax;
    }
    IRL_Fact=size.LengthFactOfIneRowN_From1stToFirstStop(IneRowN);
    if(IRL_Fact>0){
        if(Q%2==0){
            Nmid=IRL_Fact/2;
        }else{
            Nmid=(IRL_Fact-1)/2;
        }
        for(N1=1; N1<=Nmid; N1++){
            N2=IRL_Fact-N1+1;
            ArrayOf2DBy1_SwapVals(X, size, N1, IneRowN, N2, IneRowN);
        }
    }
}
