template <typename T>void ArrayOf2Dv1_AddExtRow_Simply(T**&X, Array2DSize&size, T*rowParam){
    int QExtRows=size.GetQExtRows(), QElts=size.GetQElements(), Lmax=size.GetMaxLength(), Lmin=size.GetMinLength(), L = Lmin==Lmax ? Lmax : size.GetLength(QExtRows);
    T val;
    T*row=NULL;
    row=new T[L];
    if(rowParam!=NULL){
        for(int i=1; i<=L; i++){
            val=rowParam[i-1];
            row[i-1]=val;
        }
    }
    Array1DAddElement(X, QExtRows, row);
    if(size.isRectangularEvenByStr() && Lmin==Lmax && L==Lmax){
        size.Set(QExtRows+1, L);
    }else{
        size.AddExt(L);
    }
    if(row!=NULL){
        delete[]row;
        row=NULL;
    }
}
