template <typename T>void ArrayOf2Dv1_InsExtRow_Simply(std::vector<std::vector<T>>&X, int ExtRowN, T*rowParam){
    Array2DSize size=GetSizeOf2DVector(X);
    int QExtRows=size.GetQExtRows(), QElts=size.GetQElements(), Lmax=size.GetMaxLength(), Lmin=size.GetMinLength(), L;//, PosN;// = size.GetLength(ExtRowN);
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    T val;
    std::vector<T>row;
    if(rowParam!=NULL){
        for(int i=1; i<=L; i++){
            val=rowParam[i-1];
            row.push_back(val);
        }
    }
    L = size.GetLength(ExtRowN);
    //PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        Array1DInsElementToN(X, row, ExtRowN);
        //
        if(size.isRectangularEvenByStr() && Lmin==Lmax && Lmax==L){
            size.Set(QExtRows+1, L);
        }else{
            size.InsExt(ExtRowN, L);
        }
    }
}
template <typename T>void ArrayOf2Dv1_InsExtRow_Simply(T**&X, Array2DSize size, int ExtRowN, T*rowParam, int L){
    int QExtRows=size.GetQExtRows(), QElts=size.GetQElements(), Lmax=size.GetMaxLength(), Lmin=size.GetMinLength();//, PosN;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    T val;
    T*row=NULL;
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        row=new T[L];
        if(rowParam!=NULL){
            for(int i=1; i<=L; i++){
                val=rowParam[i-1];
                row[i-1]=val;
            }
        }
        L = size.GetLength(ExtRowN);
        //PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        Array1DInsElementToN(X, QExtRows, row, ExtRowN);
        //
        if(size.isRectangularEvenByStr() && Lmin==Lmax && Lmax==L){
            size.Set(QExtRows+1, L);
        }else{
            size.InsExt(ExtRowN, L);
        }
        //
        if(row!=NULL){
            delete[]row;
            row=NULL;
        }
    }
}
template <typename T>void ArrayOf2Dv1_InsExtRow_Simply(std::vector<std::vector<T>>&X, int ExtRowN, T*rowParam, int L){
    Array2DSize size=GetSizeOf2DVector(X);
    int QExtRows=size.GetQExtRows(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength();
    bool isRect=size.isRectangularEvenByStr();
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    T val;
    std::vector<T>row;
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        if(rowParam!=NULL){
            for(int i=1; i<=L; i++){
                val=rowParam[i-1];
                row.push_back(val);
            }
        }
        L = size.GetLength(ExtRowN);
        //PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
        Array1DInsElementToN(X, row, ExtRowN);
        //
        Lmin=size.GetMinLength();
        Lmax=size.GetMaxLength();
        if(isRect && size.isRectangularEvenByStr()==false && Lmin==Lmax && Lmax==L){
            size.Set(QExtRows+1, L);
        }else{
            size.InsExt(ExtRowN, L);
        }
        //
    }
}
