template<typename T>bool ArrayOf2Dv1_ValIsAtPos(T*X, const Array2DSize&size, const T& valExt, int ExtRowN=1, int IneRowN=1){
    bool verdict=false;
    int PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
    T valIne;
    if(PosN==0){
        verdict=false;
    }else{
        valIne=X[PosN-1];
        verdict=(valIne==valExt);
    }
    return verdict;
}
template<typename T>bool ArrayOf2Dv1_ValIsAtPos(std::vector<T>X, const Array2DSize&size, const T& valExt, int ExtRowN=1, int IneRowN=1){
    return ArrayOf2Dv1_ValIsAtPos(X.data(), &size, valExt, ExtRowN, IneRowN);
}
template<typename T>std::vector<std::vector<int>>ArrayOf2Dv1_Seek_SingleVal_Simply(T*X,const  Array2DSize&size, const T& valExt){
    std::vector<std::vector<int>>Ns;
    std::vector<int>pair;
    bool b;
    int QExtRows=size.GetQExtRows(), Lcur;
    for(int i=1; i<=QExtRows; i++){
        Lcur=size.GetLength(i);
        for(int j=1; j<=Lcur; j++){
            b=ArrayOf2Dv1_ValIsAtPos(X, size, valExt, i, j);
            if(b){
                pair.clear();
                pair.push_back(i);
                pair.push_back(j);
                Ns.push_back(pair);
            }
        }
    }
    return Ns;
}
template<typename T>std::vector<std::vector<int>>ArrayOf2Dv1_Seek_SingleVal_Simply(std::vector<T>X, const Array2DSize&size, const T& valExt){
    return ArrayOf2Dv1_ValIsAtPos(X, size, valExt);
}
template<typename T>bool ArrayOf2Dv1_ExtSubRowIsAtPos_Simply(T*X, const Array2DSize&size, T*row, int L, int ExtRowN=1, int IneRowN=1, bool SoughtNotReversed=true){
    int QExtRows=size.GetQExtRows(), Lmax=size.GetMaxLength(), Lcur, PosN;
    //std::vector<T>rowWhere, rowWhat;
    T valExt, valIne;
    bool b=false;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        Lcur=size.GetLength(ExtRowN);
        if(SoughtNotReversed){
            if(IneRowN>=1 && IneRowN+L-1<=Lcur){
                b=true;
                for(int i=1; i<=L; i++){
                    valExt=row[i-1];
                    PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN+i-1);
                    valIne=X[PosN-1];
                    if(!(valExt==valIne)){
                        b=false;
                    }
                }
            }
        }else{//reversed
            if(IneRowN-L+1>=1 && IneRowN<=Lcur){
                b=true;
                for(int i=1; i<=L; i++){
                    valExt=row[i-1];
                    PosN=size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN-i+1);
                    valIne=X[PosN-1];
                    if(!(valExt==valIne)){
                        b=false;
                    }
                }
            }
        }
    }
    return b;
}
