// get SubArray by concat
//
template <typename T> void ArrayOf2Dv1_GetSubArray_AsSuccOfExtRows(T**X1, const Array2DSize& size1, T**&XR, Array2DSize& sizeR, T DefaultVal, TDataShiftParams*DataShiftParam, int DfltRowL_00_11_Lmin2_Lmax3=3){
    TDataShiftParams DataShift;
    if(DataShiftParam!=NULL){
        DataShift=(*(DataShiftParam));
    }
    std::vector<T> arR, row, rowDflt;
    int defaultL;
    int QER1=size1.GetQExtRows(), Lmin=size1.GetMinLength, Lmax=size1.GetMaxLength(),
        preN2=DataShift.GetPreN2(QER1),
            ownN1=DataShift.GetOwnN1Own(QER1), ownN2=DataShift.GetOwnN2Own(QER1),
            postN1=DataShift.GetPostN1(QER1),  postN2=DataShift.GetPostN2(QER1);
    if(XR!=NULL){
        delete[]XR;
    }
    sizeR.SetNull();
    switch(DfltRowL_00_11_Lmin2_Lmax3){
        case 0:
            defaultL=0;
        break;
        case 1:
            defaultL=1;
        break;
        case 2:
            defaultL=Lmin;
        break;
        case 3:
            defaultL=Lmax;
        break;
    }
    for(int i=1; i<=defaultL; i++){
        rowDflt.push_back(DefaultVal);
    }
    if(preN2>0){
        for(int i=1; i<=preN2; i++){
            ArrayOf2Dv1_AddExtRow(XR, sizeR, DefaultVal, rowDflt.data(), rowDflt.size());
        }
    }
    if(ownN2>0){
        for(int i=ownN1; i<=ownN2; i++){
            row=ArrayOf2Dv1_GetExtRowN_AsStdVector(X1, size1, i);
            //ArrayOf2Dv1_AddExtRow(XR, sizeR, DefaultVal, rowDflt.data(), rowDflt.size());
            ArrayOf2Dv1_AddExtRow(XR, sizeR, DefaultVal, row.data(), row.size());
        }
    }
    if(postN2>0){
        for(int i=postN1; i<=postN2; i++){
            ArrayOf2Dv1_AddExtRow(XR, sizeR, DefaultVal, rowDflt.data(), rowDflt.size());
        }
    }
    if(sizeR.GetMinLength()==sizeR.GetMaxLength() && sizeR.isRectangularEvenByStr()==false){
        sizeR.Set(sizeR.GetQExtRows(), sizeR.GetMaxLength());
    }
}
