template<typename T> bool Array2D_Prototype<T>::NsBelongHere(int ExtRowN, int IneRowN) const{
    bool verdict=true;
    int QExtRows=this->GetQExtRows(), CurLineLength;
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(ExtRowN<1 || ExtRowN>QExtRows){
        verdict=false;
    }else{
        CurLineLength=this->GetLength(ExtRowN);
        if(ExtRowN<0){
            ExtRowN+=(CurLineLength+1);
        }
        if(ExtRowN<1 && ExtRowN>CurLineLength){
            verdict=false;
        }
    }
    return verdict;
}
