template<typename T> std::vector<T> Array2D_Prototype<T>::GetIneRowN_AsArray(int IneRowN, const T& defaultVal, int ifNGTLmin_Ignore0_DefaultsForShorter1_NurProperL_AnyExtRow2_NurFromStartTillErstStop3) const{
    std::vector<T>R;
    T val;
    int curL;
    bool contin;
    int QExtRows=this->GetQExtRows(), CurRowLength=0, Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(), L1=this->GetLength(1);
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(IneRowN>=1 && IneRowN<=Lmax){
        if(IneRowN<=Lmin){
            for(int i=1; i<=QExtRows; i++){
                val=this->GetComponent_AsVal(i, IneRowN);
                R.push_back(val);
            }
        }else{
            switch(ifNGTLmin_Ignore0_DefaultsForShorter1_NurProperL_AnyExtRow2_NurFromStartTillErstStop3){
                case 0:
                    //NOP;
                break;
                case 1:
                    for(int i=1; i<=QExtRows; i++){
                        curL=this->GetLength(i);
                        if(IneRowN<=curL){
                            val=this->GetComponent_AsVal(i, IneRowN);
                            R.push_back(val);
                        }else{
                            R.push_back(defaultVal);
                        }
                    }
                break;
                case 2:
                    for(int i=1; i<=QExtRows; i++){
                        curL=this->GetLength(i);
                        if(IneRowN<=curL){
                            val=this->GetComponent_AsVal(i, IneRowN);
                            R.push_back(val);
                        }else{
                            //NOp
                        }
                    }
                break;
                case 3:
                    if(L1>=IneRowN){
                        for(int i=1; i<=QExtRows; i++){
                            curL=this->GetLength(i);
                            if(IneRowN<=curL){
                                val=this->GetComponent_AsVal(i, IneRowN);
                                R.push_back(val);
                            }else{
                                break;
                            }
                        }
                    }
                break;
            }
        }
    }//else NOp
    return R;
}
template<typename T> std::vector<T> Array2D_Prototype<T>::GetIneRowN_AsArray(int IneRowN, T*DefaultValParam, int ifNGTLmin_Ignore0_DefaultsForShorter1_NurProperL_AnyExtRow2_NurFromStartTillErstStop3) const{
    T defaultVal;
    if(DefaultValParam!=NULL){
        defaultVal=(*(DefaultValParam));
    }
    //std::vector<T> GetIneRowN_AsArray(int IneRowN, const T& defaultVal,  int ifNGTLmin_Ignore0_DefaultsForShorter1_NurProperL_AnyExtRow2_NurFromStartTillErstStop3=0) const;
    return GetIneRowN_AsArray(              IneRowN,          defaultVal,      ifNGTLmin_Ignore0_DefaultsForShorter1_NurProperL_AnyExtRow2_NurFromStartTillErstStop3);
}
