    Array2DSize size = this->GetSize(), size1=size;
    T val;
    size1.AddOrInsIneRow();
    this->SetSize(size1);
    for(int i=1; i<=QExtRows; i++){
        val=rowParam[i-1];
        curL=size1.GetLength(i);
        this->SetComponent(val, i, curL);
    }
