//
// Swap
//
template<typename T> void Array2D_Prototype<T>::SwapVals(int ExtRowN1, int IneRowN1, int ExtRowN2, int IneRowN2){
    int QExtRows=this->GetQExtRows(), L1, L2;
    T val1, val2, buf;
    if(ExtRowN1<0){
       ExtRowN1+=(QExtRows+1);
    }
    if(ExtRowN2<0){
       ExtRowN2+=(QExtRows+1);
    }
    if(ExtRowN1>=1 && ExtRowN1<=QExtRows && ExtRowN2>=1 && ExtRowN2<=QExtRows){
        L1=this->GetLength(ExtRowN1);
        L2=this->GetLength(ExtRowN2);
        if(IneRowN1>=1 && IneRowN1<=L1 && IneRowN2>=1 && IneRowN2<=L2){
            val1=this->GetComponent_AsVal(ExtRowN1, IneRowN1);
            val2=this->GetComponent_AsVal(ExtRowN2, IneRowN2);
            //
            buf=val1;
            val1=val2;
            val2=buf;
            //
            this->SetComponent(val1, ExtRowN1, IneRowN1);
            this->SetComponent(val2, ExtRowN2, IneRowN2);
        }
    }
}
//
//virtual void SwapExtRows(int N1, int N2)=0;
template<typename T> void Array2D_Prototype<T>::SwapExtRows(int N1, int N2){
    std::vector<T> row1to2, row2to1;
    int QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), L1, L2;
    if(N1<0){
        N1+=(Lmax+1);
    }
    if(N2<0){
        N2+=(Lmax+1);
    }
    L1=this->GetLength(N1);
    L2=this->GetLength(N2);
    if(N1>=1 && N1<=QExtRows && N2>=1 && N2<=QExtRows){
        row1to2=this->GetExtRowN_AsArray(N1);
        row1to2=this->GetExtRowN_AsArray(N2);
        this->SetExtRow_Simply(N1, row2to1.data(), row2to1.size());
        this->SetExtRow_Simply(N2, row1to2.data(), row1to2.size());
    }
}
//virtual void SwapExtRows_Simply(int N1, int N2)=0;
//virtual void SwapExtRows_Simply(int N1, int N2)=0;
//virtual   void SwapIneRows(int N1, int N2)=0;
template<typename T> void Array2D_Prototype<T>::SwapIneRows(int N1, int N2){
    std::vector<T> row1to2, row2to1;
    int QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(),L1, L2;
    if(N1<0){
        N1+=(Lmax+1);
    }
    if(N2<0){
        N2+=(Lmax+1);
    }
    L1=this->GetLength(N1);
    L2=this->GetLength(N2);
    if(N1>=1 && N1<=Lmax && N2>=1 && N2<=Lmax){
        if(N1<=Lmin && N2<=Lmin){
            row1to2=this->GetIneRowN_AsArray(N1);
            row1to2=this->GetIneRowN_AsArray(N2);
            this->SetIneRow_Simply(N1, row2to1.data());//, row2to1.size());
            this->SetIneRow_Simply(N2, row1to2.data());//, row1to2.size());
        }
    }
}
//
// Reverse
//
//void ReverseExtRowN(int rowN);
template<typename T> void Array2D_Prototype<T>::ReverseExtRowN(int rowN){
    int curL=this->GetLength(rowN), midN, N1, N2;
    if(curL>0){
        if(curL%2==0){
            midN=curL/2;
        }else{
            midN=(curL-1)/2;
        }
    }
    for(N1=1; N1<=midN; N1++){
        N2=curL-N1+1;
        this->SwapVals(rowN, N1, rowN, N2);
    }
}
//virtual void ReverseExtRowsSuccession()=0;
//virtual void ReverseExtRowsSuccession();
template<typename T> void Array2D_Prototype<T>::ReverseIneRowN(int IneRowN){
    Array2DSize size=this->GetSize();
    std::vector<T>data=this->GetContent_AsArray1D();
    int Q=size.GetQExtRows(), Lmin=size.GetMinLength(), Lmax=size.GetMaxLength(), Nmid, N1, N2, IRL_fact;
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    IRL_fact=size.LengthFactOfIneRowN_From1stToFirstStop(IneRowN);
    //if(Q>0 && IneRowN>=1 && IneRowN<=Lmin){
    if(IRL_fact>0){
        if(IRL_fact%2==0){
            Nmid=IRL_fact/2;
        }else{
            Nmid=(IRL_fact-1)/2;
        }
        for(N1=1; N1<=Nmid; N1++){
            N2=IRL_fact-N1+1;
            ArrayOf2DBy1D_SwapVals(data, size, N1, IneRowN, N2, IneRowN);
        }
    }
}

//virtual void ReverseExtRowsSuccession()=0;
//void ReverseExtRowsSuccession()
template<typename T> void Array2D_Prototype<T>::ReverseExtRowsSuccession(){
    int QExtRows=this->GetQExtRows(), rowL, Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(), midN, N1, N2;
    std::vector<T>row1, row2;
    if(N1<0){
        N1+=(QExtRows+1);
    }
    if(N2<0){
        N2+=(QExtRows+1);
    }
    if(QExtRows%2==0){
        midN=QExtRows/2;
    }else{
        midN=(QExtRows-1)/2;
    }
    for(N1=1; N1<=midN; N1++){
        N2=QExtRows-N1+1;
        row1=this->GetExtRowN_AsArray(N1);
        row2=this->GetExtRowN_AsArray(N2);
        this->SetExtRow_Simply(N1, row2.data(), row2.size());
        this->SetExtRow_Simply(N2, row1.data(), row1.size());
    }
}
template<typename T> void Array2D_Prototype<T>::ReverseIneRowsSuccession(){
    int QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(), midN, N1, N2, rowL=Lmax;
    std::vector<T>row1, row2;
    if(N1<0){
        N1+=(Lmax+1);
    }
    if(N2<0){
        N2+=(Lmax+1);
    }
    if(Lmin==Lmax){
        if(QExtRows%2==0){
            midN=Lmax/2;
        }else{
            midN=(Lmax-1)/2;
        }
        for(N1=1; N1<=midN; N1++){
            N2=Lmax-N1+1;
            row1=this->GetIneRowN_AsArray(N1);
            row2=this->GetIneRowN_AsArray(N2);
            this->SetExtRow_Simply(N1, row2.data(), row2.size());
            this->SetExtRow_Simply(N2, row1.data(), row1.size());
        }
    }
}
