template<typename T> bool Array2D_Prototype<T>::ValIsAtPos(const T&val, int ExtRowN, int IneRowN) const{//swa di prototype n'fit. Obe s' ERN alt IRN, so ERN 2x
    bool b=false;
    int QExtRows=this->GetQExtRows(), L;
    T ownVal;
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        L=this->GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN<=L){
            ownVal=this->GetComponent_AsVal(ExtRowN, IneRowN);
            if(val==ownVal){
                b=true;
            }
        }
    }
    return b;
}
