template<typename T> TListOfNumberPairs Array2D_Prototype<T>::SeekVal(const T&val) const{
    TListOfNumberPairs Ns;
    bool b;
    int QExtRows=this->GetQExtRows(), L;
    for(int i=1; i<=QExtRows; i++){
        L=this->GetLength(i);
        for(int j=1; j<=L; j++){
            b=this->ValIsAtPos(val, i, j);
            if(b==true){
                Ns.Add(i, j);
            }
        }
    }
    return Ns;
}
template<typename T> bool Array2D_Prototype<T>::ExtRowIsAtPos(T*row, int Q, int ExtRowN, int IneRowN) const{
    bool b=true;
    int QExtRows=this->GetQExtRows(), L;
    T ownVal;
    if(ExtRowN>=1 && ExtRowN<=QExtRows){
        L=this->GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN+Q-1<=L){
            for(int i=1; i<=Q; i++){
                ownVal=this->GetComponent_AsVal(ExtRowN, IneRowN+i-1);
                if(!(ownVal==row[i-1])){
                    b=false;
                }
            }
        }
    }
    return b;
}
