template<typename T> TListOfNumberPairs Array2D_Prototype<T>::SeekExtRow(T*row, int rowL) const{
    TListOfNumberPairs Ns;
    bool b;
    int QExtRows=this->GetQExtRows(), curL;
    for(int i=1; i<=QExtRows; i++){
        curL=this->GetLength(i);
        for(int j=1; j<=curL-rowL+1; j++){
            b=this->ExtRowIsAtPos(row, rowL, i, j);
            if(b==true){
                Ns.Add(i, j);
            }
        }
    }
    return Ns;
}
template<typename T> bool Array2D_Prototype<T>::IneRowIsAtPos(T*row, int Q, int ExtRowN, int IneRowN) const{
    bool b=true;
    int QExtRows=this->GetQExtRows(), L;
    T ownVal;
    if(ExtRowN>=1 && ExtRowN+Q-1<=QExtRows){
        L=this->GetLength(ExtRowN);
        if(IneRowN>=1 && IneRowN<=L){
            for(int i=1; i<=Q; i++){
                L=this->GetLength(i);
                if(IneRowN>L){
                    b=false;
                }
            }
            if(b==true){
                for(int i=1; i<=Q; i++){
                    ownVal=this->GetComponent_AsVal(ExtRowN+i-1, IneRowN);
                    if(!(ownVal==row[i-1])){
                        b=false;
                    }
                }
            }
        }
    }
    return b;
}
