template <typename T> void Array2D_Prototype<T>::ArrayOf2DBy1D_ValSetOrAddOrFillOrIgnore(T val, int ExtRowN, int IneRowN, T DefaultVal, int SetRect_No0IfPossible1AnywayYes2){//, int DfltRowL_00_11_Max2_Min3)template <typename T> void Array2D_Prototype<T>::ArrayOf2DBy1D_ValSetOrAddOrFillOrIgnore(T val, int ExtRowN, int IneRowN, T DefaultVal, int SetRect_No0IfPossible1AnywayYes2=1){//, int DfltRowL_00_11_Max2_Min3){
    std::vector<T>row;
    int QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(),  Lcur;
    //bool isRect;
    Array2DSize size;
    //isRect=size.isRectangularEvenByStr();
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    if(IneRowN<0){
        IneRowN+=(Lmax+1);
    }
    if(ExtRowN==0 && IneRowN==0){
        for(int i=1; i<=QExtRows; i++){
            Lcur=this->GetLength(i);
            for(int j=1; j<=Lcur; j++){
                this->SetComponent(val, i, j);
            }
        }
    }else if(ExtRowN==0 && IneRowN!=0){
        if(IneRowN>=1 && IneRowN<=Lmax){
            for(int i=1; i<=QExtRows; i++){
                Lcur=this->GetLength(i);
                if(IneRowN>=Lcur){
                    this->SetComponent(val, i, IneRowN);
                }
            }
        }else if(IneRowN==Lmax+1){
            if(Lmin!=Lmax){
                for(int i=1; i<=QExtRows; i++){
                    Lcur=this->GetLength(i);
                    if(IneRowN>=Lmax){
                        for(int j=Lcur+1; j<=Lmax; j++){
                            this->AddToExtRowN_Simply(i, DefaultVal);
                        }
                        this->AddToExtRowN_Simply(i, val);
                    }
                }
            }
        }//else ignore
    }else if(ExtRowN!=0 && IneRowN==0){
        if(ExtRowN>=1 && ExtRowN<=QExtRows){
            Lcur=this->GetLength(ExtRowN);
            for(int i=1; i<=Lcur; i++){
                this->SetComponent(val, ExtRowN, i);
            }
        }else if(ExtRowN==QExtRows+1){
            row.clear();
            Lcur=this->GetLength(ExtRowN);
            for(int i=1; i<=Lcur; i++){
                row.push_back(val);
            }
            this->AddExtRow(row.data(), row.size());
        }//else NOp, ignore
    }else{//both !=0, no fill
        if(ExtRowN>=1 && ExtRowN<=QExtRows){
            Lcur=this->GetLength(ExtRowN);
            if(IneRowN>=1 && IneRowN<=Lcur){
                this->SetComponent(val, ExtRowN, IneRowN);
            }else if(IneRowN==Lmax+1){
                for(int i=Lcur+1; i<=Lmax+1; i++){
                    this->AddToExtRowN_Simply(i, DefaultVal);
                }
                this->SetComponent(val, ExtRowN, Lcur+1);
            }//else NOp, ignore
        }else if(ExtRowN==QExtRows+1){
            if(IneRowN>=1 && IneRowN<=Lmax){
                for(int i=1; i<=IneRowN; i++){
                    row.push_back(val);
                }
                this->AddExtRow(row.data(), row.size());
            }else if(IneRowN==Lmax+1){
                this->SetSize(DefaultVal, QExtRows+1, Lmax+1);
               this->SetComponent(val, ExtRowN, IneRowN);
            }//else NOp, ignore
        }//else NOp, ignore
    }
    //
    QExtRows=this->GetQExtRows();
    Lmin=this->GetMinLength();
    Lmax=this->GetMaxLength();
    size=this->GetSize();
    //ce af resisze
    switch(SetRect_No0IfPossible1AnywayYes2){
        //case 0 - default - NOp
        case 1:
            if(size.isRectangularEvenByStr()==false && Lmin==Lmax){
                size.Set(QExtRows, Lmax);
            }
        break;
        case 2:
            if(size.isRectangularEvenByStr()==false){
                if(Lmin!=Lmax){
                    this->SetSize(DefaultVal, QExtRows, Lmax);
                }
                size.Set(QExtRows, Lmax);
            }
        break;
    }
}//fn
