// Std Cout
//
template<typename T> void Array2D_Prototype<T>::StdCout_ExtRowN(int ExtRowN, QString ElemsDelim, bool UseBrackets)const{
    int curL=this->GetLength(ExtRowN);
    T val;
    if(UseBrackets)std::cout<<"[";
    for(int i=1; i<=curL-1; i++){
        val=this->GetComponent_AsVal(ExtRowN, i);
        std::cout<<val;
        std::cout<<ElemsDelim.toStdString().c_str();
    }
    val=this->GetComponent_AsVal(ExtRowN, curL);
    std::cout<<val;
    if(UseBrackets)std::cout<<"]";
}

template<typename T> void Array2D_Prototype<T>::StdCout_IneRowN(int IneRowN, QString ElemsDelim, bool UseBrackets, bool Repr2DNot1D)const{
    Array2DSize size=this->GetSize();
    int curL=size.LengthFactOfIneRowN_From1stToFirstStop(IneRowN);
    T val;
    if(UseBrackets)std::cout<<"[";
    for(int i=1; i<=curL-1; i++){
        val=this->GetComponent_AsVal(i, IneRowN);
        std::cout<<val;
        std::cout<<ElemsDelim.toStdString().c_str();
        if(Repr2DNot1D)std::cout<<std::endl;
    }
    val=this->GetComponent_AsVal(curL, IneRowN);
    std::cout<<val;
    if(UseBrackets)std::cout<<"]";
    if(Repr2DNot1D)std::cout<<std::endl;
}
//                   void                       StdCout(QString ElemsDelim=", ", RowsDelim="; ", bool UseBrackets=true, bool Represent2DNot1D=true, bool ByExtRowsNotIneRows=true)const;
template<typename T> void Array2D_Prototype<T>::StdCout(QString ElemsDelim, QString RowsDelim, bool UseBrackets, bool Represent2DNot1D, bool ByExtRowsNotIneRows)const{
    int QER=this->GetQExtRows(), Lmax=this->GetMaxLength(), curL;
    if(ByExtRowsNotIneRows){
        if(UseBrackets)std::cout<<"[";
        StdCout_ExtRowN(1, ElemsDelim, UseBrackets);
        std::cout<<RowsDelim.toStdString().c_str();
        if(Represent2DNot1D)std::cout<<std::endl;
        for(int ERN=2; ERN<=QER-1; ERN++){
             if(Represent2DNot1D)std::cout<<" ";
             StdCout_ExtRowN(ERN, ElemsDelim, UseBrackets);
             std::cout<<RowsDelim.toStdString().c_str();
             if(Represent2DNot1D)std::cout<<std::endl;
        }
        if(Represent2DNot1D)std::cout<<" ";
        StdCout_ExtRowN(QER, ElemsDelim, UseBrackets);
        if(Represent2DNot1D)std::cout<<std::endl;
        if(UseBrackets)std::cout<<"]";
    }else if(this->GetSize().IsForTranspose()){
        if(UseBrackets)std::cout<<"[";
        StdCout_IneRowN(1, ElemsDelim, UseBrackets);
        std::cout<<RowsDelim.toStdString().c_str();
        if(Represent2DNot1D)std::cout<<std::endl;
        for(int ERN=2; ERN<=Lmax-1; ERN++){
             if(Represent2DNot1D)std::cout<<" ";
             StdCout_IneRowN(ERN, ElemsDelim, UseBrackets);
             std::cout<<RowsDelim.toStdString().c_str();
             if(Represent2DNot1D)std::cout<<std::endl;
        }
        if(Represent2DNot1D)std::cout<<" ";
        StdCout_IneRowN(Lmax, ElemsDelim, UseBrackets);
        if(Represent2DNot1D)std::cout<<std::endl;
        if(UseBrackets)std::cout<<"]";
    }
}

