template<typename T> Array2D_P1L<T>* Array2D_P1L<T>::GetSubArray(int ExtRowN, int IneRowN, const Array2DSize& size, bool isNotTransposed, bool ExtRowsSuccIsNotReversed, bool EachExtRowIsNotReversed) const{
    Array2D_P1L<T>*data;
    T defaultVal, curVal;
    int QExtRows=size.GetQExtRows(), curL, ExtRowN1, IneRowN1, QExtRowsWhere=this->GetQExtRows();
    Int2DVectorOfSizeOrCoords CoordsWhereFrom, CoordsInWhat, CoordsWhereTo;
    data=new  Array2D_P1L<T>();
    data->SetSize(defaultVal, size);
    CoordsWhereFrom.d1=ExtRowN;
    CoordsWhereFrom.d2=IneRowN;
    for(int i=1; i<=QExtRows; i++){
        curL=size.GetLength(i);
        for(int j=1; j<=curL; j++){
            CoordsInWhat.d1=i;
            CoordsInWhat.d2=j;
            CoordsWhereTo=Array2DCoordsTransform(CoordsWhereFrom, CoordsInWhat, isNotTransposed, ExtRowsSuccIsNotReversed, EachExtRowIsNotReversed);
            ExtRowN1=CoordsWhereTo.d1;
            IneRowN1=CoordsWhereTo.d2;
            if(ExtRowN1>=1 &&ExtRowN1<=QExtRowsWhere){
                curL=this->GetLength(ExtRowN1);
                if(IneRowN1>=1 && IneRowN1<=curL){
                    curVal=this->GetComponent_AsVal(ExtRowN1, IneRowN1);
                }else{
                    curVal=defaultVal;
                }
            }else{
                curVal=defaultVal;
            }
            data->SetComponent(curVal, i, j);
        }
    }
    return data;
}

