template<typename T> Array2D_P1L<T>* Array2D_P1L<T>::GetSubArray_AsSuccOfExtRows(T DefaultVal, TDataShiftParams*DataShiftParam,                         int DfltRowL_00_11_Lmin2_Lmax3){
    T*XR;
    Array2DSize sizeR;
    Array2D_P1L*Arr;
    //void GetSubArray_AsSuccOfExtRows_As1DArr(T*&XR, Array2DSize& sizeR, T DefaultVal, DataShiftParams*DataShiftParam=NULL,  int DfltRowL_00_11_Lmin2_Lmax3=3);
    this-> GetSubArray_AsSuccOfExtRows_As1DArr(   XR,              sizeR,   DefaultVal,                 DataShiftParam,            DfltRowL_00_11_Lmin2_Lmax3);
    Arr=new Array2D_P1L(XR, size);
    return Arr;
}
