template<typename T> Array2D_P1L<T>* Array2D_P1L<T>::GetSubArray_AsSuccOfExtRows( TDataShiftParams*DataShiftParam, T*DefaultValParam, int DfltRowL_00_11_Lmin2_Lmax3){
    T DefaultVal;
    if(DefaultValParam!=NULL){
        DefaultVal=(*(DefaultValParam));
    }
    //virtual Array2D_Prototype* GetSubArray_AsSuccOfExtRows(T DefaultVal, TDataShiftParams*DataShiftParam=NULL, int DfltRowL_00_11_Lmin2_Lmax3=3)=0;
    return                 this->GetSubArray_AsSuccOfExtRows(  DefaultVal,                  DataShiftParam,          DfltRowL_00_11_Lmin2_Lmax3);
}
