    ////virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T DefaultVal)=0;
    //virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T DefaultVal);
    template<typename T> void Array2D_V1I<T>::SetLengthOfExtRowN(int ExtRowN, int newL, T DefaultVal){
        //ArrayOf2DBy1D_SetLengthOfExtRowN(this->data, this->size,ExtRowN,newL, DefaultVal);
        int QExtRows=this->GetQExtRows(), oldL, erstPosN, curPosN;
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows){
            oldL=this->GetLength(ExtRowN);
            if(oldL<newL){
                if(ExtRowN<QExtRows){
                    erstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, oldL+1);
                    for(int i=1; i<=newL-oldL; i++){
                        curPosN=erstPosN+i-1;
                        this->data.insert(this->data.begin()+curPosN-1, DefaultVal);
                    }
                }else{
                    for(int i=1; i<=newL-oldL; i++){
                        this->data.push_back(DefaultVal);
                    }
                }
            }else if(oldL>newL){
                erstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, newL);
                curPosN=erstPosN;
                for(int i=1; i<=oldL-newL; i++){
                    //curPosN=erstPosN+i-1;
                    this->data.erase(this->data.begin()+curPosN-1);
                }
            }
            this->size.SetLength(newL, ExtRowN);
        }
    }
    //
    ////virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T*DefaultValParam=NULL)=0;
    //virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T*DefaultValParam=NULL);
    template<typename T> void Array2D_V1I<T>::SetLengthOfExtRowN(int ExtRowN, int newL, T*DefaultValParam){
        // ArrayOf2DBy1D_SetLengthOfExtRowN(this->data, this->size,ExtRowN,newL,DefaultValParam);
        T DefaultVal;
        if(DefaultValParam!=NULL){
            DefaultVal=* DefaultValParam;
        }
        this->SetLengthOfExtRowN(ExtRowN, newL, DefaultVal);
    }
    //virtual void SetSize(const T& DfltValParam, const Array2DSize&size)=0;
    template<typename T> void Array2D_V1I<T>::SetSize(const T& DefaultVal, const Array2DSize&sizeNew){
        ////Array2DSize sizeOld=this->GetSize();
        ////ArrayOf2DBy1D_SetSize(this->data, sizeOld, sizeNew, DfltValParam, true);
        //ArrayOf2DBy1D_SetSize(this->data, this->size, sizeNew, DfltValParam, true);
        Array2DSize sizeOld=this->GetSize();
        int QEltsOld=sizeOld.GetQElements(), QEltsNew=sizeOld.GetQElements(), QExtRowsOld=sizeOld.GetQExtRows(), QExtRowsNew=sizeOld.GetQExtRows(), curL, oldL, newL, PosN, QERMin;
        if(QExtRowsOld<QExtRowsNew){
            for(int i=QExtRowsOld+1; i<=QExtRowsNew; i++){
                curL=sizeNew.GetLength(i);
                this->data.push_back(DefaultVal);
            }
            for(int i=1; i<=QExtRowsOld; i++){
                newL=sizeNew.GetLength(i);
                this->SetLengthOfExtRowN(i,newL, DefaultVal);
            }
        }else if(QExtRowsOld>QExtRowsNew){
            PosN=this->size.GetPositionByCoordsIfRealizedAs1D(QExtRowsNew, 1);
            for(int i=QExtRowsNew; i<=QExtRowsOld; i++){
                this->data.erase(this->data.begin()+PosN-1);
            }
            for(int i=1; i<=QExtRowsOld; i++){
                newL=sizeNew.GetLength(i);
                this->SetLengthOfExtRowN(i,newL, DefaultVal);
            }
        }
        this->size=sizeNew;
    }
