    template<typename T> int Array2D_V1I<T>::GetPosN(int ExtRowN, int IneRowN) const{
        int PosN, curL;
        //PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        PosN=0;
        for(int i=1; i<=ExtRowN-1; i++){
            curL=this->size.GetLength(i);
            PosN+=curL;
        }
        curL=this->size.GetLength(ExtRowN-1);
        if(IneRowN>curL){
            PosN=0;
        }else{
            PosN=IneRowN;
        }
        //PosN=(ExtRowN-1)*curL+IneRowN;
        return PosN;
    }
    template<typename T> T Array2D_V1I<T>::GetComponent_AsVal(int ExtRowN, int IneRowN) const{
        T val;
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        val=this->data[PosN-1];
        return val;
    }
    //virtual T* GetComponent_AsPtr(int LineN, int ColN) const=0;
    template<typename T> T* Array2D_V1I<T>::GetComponent_AsPtr(int ExtRowN, int IneRowN) const{
        T*ptr;
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        ptr=this->data[PosN-1];
        return ptr;
    }
    //
    //virtual void SetComponent(const T& val, int LineN, int ColN)=0;
    template<typename T> void Array2D_V1I<T>::SetComponent(const T& val, int ExtRowN, int IneRowN){
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        this->data[PosN-1]=val;
    }
    //
    template<typename T> void Array2D_V1I<T>::AddToExtRowN_Simply(int ExtRowN, const T&val){
        int curL=this->size.GetLength(ExtRowN);
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, curL);
        if(ExtRowN<this->GetQExtRows()){
            this->data.insert(this->data.begin()+PosN-1, val);
        }else{
            this->data.push_back(val);
        }
        this->size.SetLength(curL+1, ExtRowN);
        //ArrayOf2DBy1D_AddToExtRowN(this->data, this->size,ExtRowN, val);
    }
    template<typename T> void Array2D_V1I<T>::InsToExtRowN_Simply(int ExtRowN, int IneRowN, const T&val){
        int curL=this->size.GetLength(ExtRowN), QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength();
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(IneRowN<0){
            IneRowN+=(Lmax+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows && IneRowN>=1 && IneRowN<=curL){
            int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
            this->data.insert(this->data.begin()+PosN-1, val);
            this->size.SetLength(curL+1, ExtRowN);
            //ArrayOf2DBy1D_InsToExtRowN(this->data, this->size, ExtRowN, val, PosN);
        }
    }
    template<typename T> void Array2D_V1I<T>::DelFromExtRowN_Simply(int ExtRowN, int IneRowPosN){
        int curL=this->size.GetLength(ExtRowN), QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength();
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(IneRowPosN<0){
            IneRowPosN+=(Lmax+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows && IneRowPosN>=1 && IneRowPosN<=curL){
            int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowPosN);
            this->data.erase(this->data.begin()+PosN-1);
            //ArrayOf2DBy1D_DelFromExtRowN(this->data,this->size,ExtRowN,IneRowPosN);
            this->size.SetLength(curL-1, ExtRowN);
        }
    }
