    //
    //virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T DefaultVal)=0;
    template<typename T> void Array2D_P1I<T>::SetLengthOfExtRowN(int ExtRowN, int newL, T DefaultVal){
        //ArrayOf2DBy1D_SetLengthOfExtRowN(this->data, this->size,ExtRowN, newL, DefaultVal);
    T val;
    int QExtRows=this->size.GetQExtRows(), QElems=this->size.GetQElements(), oldL, erstPosN, curPosN;
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows){
            oldL=this->GetLength(ExtRowN);
            if(oldL<newL){
                if(ExtRowN==QExtRows){
                    for(int i=oldL; i<=newL; i++){
                        VectorAddVal(this->data, QElems, DefaultVal);
                    }
                }else{
                    erstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, oldL);
                    for(int i=oldL; i<=newL; i++){
                        curPosN=erstPosN+i-1;
                        VectorInsVal(this->data, QElems, curPosN, DefaultVal);
                    }
                }
            }else if(oldL>newL){
                erstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, newL+1);
                curPosN=erstPosN;
                for(int i=newL; i<=oldL; i++){
                    VectorDelVal(this->data, QElems, curPosN);
                }
            }
            this->size.SetLength(newL, ExtRowN);
        }
    }
    //virtual void SetLengthOfExtRowN(int ExtRowN, int newL, T*DefaultValParam=NULL)=0;
    template<typename T> void Array2D_P1I<T>::SetLengthOfExtRowN(int ExtRowN, int newL, T*DefaultValParam){
        //ArrayOf2DBy1D_SetLengthOfExtRowN(this->data, this->size,ExtRowN, newL, DefaultValParam);
        T DefaultVal;
        if(DefaultValParam!=NULL){
            DefaultVal=*DefaultValParam;
        }
        this->SetLengthOfExtRowN(ExtRowN, newL, DefaultVal);
    }
    //
    //virtual void SetSize(const T& DfltValParam, const Array2DSize&size)=0;
    template<typename T> void Array2D_P1I<T>::SetSize(const T& DefaultVal, const Array2DSize&sizeNew){
        ////Array2DSize sizeOld=this->GetSize();
        ////ArrayOf2DBy1D_SetSize(this->data, sizeOld, sizeNew, DfltValParam, true);
        //ArrayOf2DBy1D_SetSize(this->data, this->size, sizeNew, DfltValParam, true);
        int QExtRowsOld=this->size.GetQExtRows(), QElemsOld=this->size.GetQElements(), QExtRowsNew=sizeNew.GetQExtRows(), QElemsNew=sizeNew.GetQElements(),
                oldL, newL, minL, minQER;
        T*y=NULL;
        if(QElemsOld!=QElemsNew){
            //VectorSetSize(this->data, QElemsOld, QElemsNew,DefaultVal);
            y=new T[QElemsNew];
        }
        minQER = QExtRowsOld <= QExtRowsNew ?  QExtRowsOld : QExtRowsNew;
        for(int i=1; i<=minQER; i++){
            //oldL=this->size.GetLength(i);
            newL=sizeNew.GetLength(i);
            this->SetLengthOfExtRowN(i, newL, DefaultVal);
        }
        //if if minQER==QWENew, so noid ady ute do, if minQER==QWEOld, so all esg'n ER's Ls s'set
        QElemsOld=this->size.GetQElements();//nu to val s'mut'd, this->size s'mut'd m'SetLengthOfExtRowN
        for(int i=minQER+1; i<=QExtRowsNew; i++){//if QExtRowsNew = minQER, to cycle ne wi gedo'd
             newL=sizeNew.GetLength(i);
             for(int j=1; j<=newL; j++){
                 VectorAddVal(this->data, QElemsOld, DefaultVal);
             }
        }
        this->size=sizeNew;
    }//fn
