    template<typename T> int Array2D_P1I<T>::GetPosN(int ExtRowN, int IneRowN) const{
        int PosN, curL;
        //PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        PosN=0;
        for(int i=1; i<=ExtRowN-1; i++){
            curL=this->size.GetLength(i);
            PosN+=curL;
        }
        curL=this->size.GetLength(ExtRowN-1);
        if(IneRowN>curL){
            PosN=0;
        }else{
            PosN=IneRowN;
        }
        //PosN=(ExtRowN-1)*curL+IneRowN;
        return PosN;
    }
    template<typename T> T Array2D_P1I<T>::GetComponent_AsVal(int ExtRowN, int IneRowN) const{
        T val;
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        val=this->data[PosN-1];
        return val;
    }
    //virtual T* GetComponent_AsPtr(int LineN, int ColN) const=0;
    template<typename T> T* Array2D_P1I<T>::GetComponent_AsPtr(int ExtRowN, int IneRowN) const{
        T*ptr;
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        ptr=this->data[PosN-1];
        return ptr;
    }
