    //virtual void SetComponent(const T& val, int LineN, int ColN)=0;
    template<typename T> void Array2D_P1I<T>::SetComponent(const T& val, int ExtRowN, int IneRowN){
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
        this->data[PosN-1]=val;
    }
    //
    template<typename T> void Array2D_P1I<T>::AddToExtRowN_Simply(int ExtRowN, const T&val){
        int curL=this->size.GetLength(ExtRowN);
        int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, curL);
        int QElems=this->size.GetQElements();
        if(ExtRowN<this->GetQExtRows()){
            VectorInsVal(this->data, QElems, PosN, val);
        }else{
            VectorAddVal(this->data, QElems, val);
        }
        this->size.SetLength(curL+1, ExtRowN);
        //ArrayOf2DBy1D_AddToExtRowN(this->data, this->size,ExtRowN, val);
    }
    template<typename T> void Array2D_P1I<T>::InsToExtRowN_Simply(int ExtRowN, int IneRowN, const T&val){
        int curL=this->size.GetLength(ExtRowN), QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), QElems=this->size.GetQElements();
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(IneRowN<0){
            IneRowN+=(Lmax+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows && IneRowN>=1 && IneRowN<=curL){
            int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowN);
            VectorInsVal(this->data, QElems, PosN, val);
            this->size.SetLength(curL+1, ExtRowN);
            //ArrayOf2DBy1D_InsToExtRowN(this->data, this->size, ExtRowN, val, PosN);
        }
    }
    template<typename T> void Array2D_P1I<T>::DelFromExtRowN_Simply(int ExtRowN, int IneRowPosN){
        int curL=this->size.GetLength(ExtRowN), QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), QElems=this->size.GetQElements();
        if(ExtRowN<0){
            ExtRowN+=(QExtRows+1);
        }
        if(IneRowPosN<0){
            IneRowPosN+=(Lmax+1);
        }
        if(ExtRowN>=1 && ExtRowN<=QExtRows && IneRowPosN>=1 && IneRowPosN<=curL){
            int PosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, IneRowPosN);
            VectorDelVal(this->data, QElems, PosN);
            //ArrayOf2DBy1D_DelFromExtRowN(this->data,this->size,ExtRowN,IneRowPosN);
            this->size.SetLength(curL-1, ExtRowN);
        }
    }
