//void SetExtRowN(int N, const T& defaultVal, T*rowParam, int rowL,  TDataShiftParams*DataShiftParams=NULL, bool DefaulsAreSpecNotOwnVals=true, int SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6=2);
//void SetExtRowN(int N, T*rowParam, int rowL, TDataShiftParams*DataShiftParams=NULL, bool DefaulsAreSpecNotOwnVals=true, T*DfltValParam=NULL, int SizeRect_DoNotCare0_Not1_IfPossible2_AnywayBy_MaxOfBoth3_MaxLIn2DArr4_OldL5_NewL6=2);
//
//void SetExtRow_Simply(int N, T*rowParam)=0;
template<typename T> void Array2D_P1I<T>::SetExtRow_Simply(int N, T*rowParam){
    T val;
    int curL=this->GetLength(N), QElems=this->size.GetQElements();
    int ErstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(N, 1), curPosN;
    for(int i=1; i<=curL; i++){
        curPosN=ErstPosN+i-1;
        val=rowParam[i-1];
        this->data[curPosN-1]=rowParam[i-1];
    }
}
//void SetExtRow_Simply(int N, T*rowParam, int L)=0;
template<typename T> void Array2D_P1I<T>::SetExtRow_Simply(int N, T*rowParam, int L){
    T val;
    int curL=this->GetLength(N), curPosN, ErstPosN, QElems=this->size.GetQElements();
    if(L==curL){
        this->SetExtRow_Simply(N, rowParam);
    }else{
         ErstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(N, 1);
         for(int i=1; i<=curL; i++){
            VectorDelVal(this->data, QElems, ErstPosN);
         }
         for(int i=1; i<=L; i++){
             curPosN=ErstPosN+i-1;
             val=rowParam[i-1];
             VectorInsVal(this->data, QElems, curPosN, val);
         }
    }
    this->size.SetLength(L, N);
}
