template<typename T> void Array2D_P1I<T>::InsExtRow_Simply(int ExtRowN, T*rowParam, int L){
    T val;
    int QExtRows=this->GetQExtRows(), curL, erstPosN, curPosN, QElems=this->size.GetQElements();
    if(ExtRowN<0){
        ExtRowN+=(QExtRows+1);
    }
    curL=this->GetLength(ExtRowN);
    erstPosN=this->size.GetPositionByCoordsIfRealizedAs1D(ExtRowN, 1);
    for(int i=1; i<=L; i++){
        curPosN=erstPosN+i-1;
        val=rowParam[i-1];
        VectorInsVal(this->data, QElems, curPosN, val);
    }
    this->size.InsExt(L, ExtRowN);
    // ArrayOf2DBy1D_InsExtRow_Simply(this->data, this->size, N, rowParam, L);
}
