template<typename T> void Array2D_P1I<T>::SetIneRow_Simply(int IneRowN, T*rowParam){
    //ArrayOf2DBy1D_SetIneRow_Simply(this->data, this->size, IneRowN, rowParam);
    T val;
    int QExtRows=this->GetQExtRows(), Lmax=this->GetMaxLength(), Lmin=this->GetMinLength(), curL, PosN;
    if(IneRowN>=1 && IneRowN<=Lmax){
        if(IneRowN<=Lmin){
            for(int i=1; i<=QExtRows; i++){
                val=rowParam[i-1];
                PosN=this->size.GetPositionByCoordsIfRealizedAs1D(i, IneRowN);
                this->data[PosN-1]=val;
            }
        }
    }
}
