template<typename T> Array2D_shell<T>::Array2D_shell(int TypeN){
    this->construct(TypeN);
    this->SetNull();
}
template<typename T> Array2D_shell<T>::Array2D_shell(T**arr, const Array2DSize& size, int TypeN){
    this->construct(TypeN);
    this->Set(arr, size, true, TypeN);
}
