template<typename T> void Array2D_shell<T>::SetTypeN(int TypeN){
    std::vector<T>arr=this->GetContent_AsArray1D();
    Array2DSize size=this->GetSize();
    bool isEmpty=(size.GetQExtRows()==0);
    delete this->data;
    this->construct(TypeN);
    this->Set(arr, size);
}
