//virtual void SetNull()=0;
template<typename T> void Array2D_shell<T>::SetNull(){
    this->data->SetNull();
}
template<typename T>void Array2D_shell<T>::construct(int TypeN){
    switch(TypeN){
        case Array2D_TypeN_V1L:
            this->data=new Array2D_V1L<T>();
        break;
        case Array2D_TypeN_P1L:
            this->data=new Array2D_P1L<T>();
        break;
    }
}
