template<typename T>Array2D_Prototype<T>* Array2D_shell<T>::GetData(int TypeNParam) const{
    //int TypeNWas=this->GetTypeN;
    Array2D_Prototype<T>*ptr;
    std::vector<T>arr=this->GetContent_AsArray1D();
    Array2DSize size=this->GetSize();
    switch(TypeNParam){
        case Array2D_TypeN_V1L:
            ptr=new Array2D_V1L<T>(arr, size);//amda n'wa <T>, rt S ecri err: expected ; af Array2D_V1L
        break;
        case Array2D_TypeN_P1L:
            ptr=new Array2D_P1L<T>(arr, size);
        break;
    }
    return ptr;
}
