//Array2D_shell<T>                                      GetSubArray_AsSuccOfExtRows(T DefaultVal, TDataShiftParams*DataShiftParam=NULL,                    int DfltRowL_00_11_Lmin2_Lmax3=3) const;
template<typename T> Array2D_shell<T> Array2D_shell<T>::GetSubArray_AsSuccOfExtRows(T DefaultVal, TDataShiftParams*DataShiftParam,                         int DfltRowL_00_11_Lmin2_Lmax3) const{
    Array2D_shell R;
    T*dataP;
    Array2DSize sizeR;
    //void      GetSubArray_AsSuccOfExtRows_As1DArr(T*&XR, Array2DSize& sizeR, T DefaultVal, DataShiftParams*DataShiftParam=NULL, int DfltRowL_00_11_Lmin2_Lmax3=3);
    this->data->GetSubArray_AsSuccOfExtRows_As1DArr(dataP,              sizeR,   DefaultVal, DataShiftParam,                          DfltRowL_00_11_Lmin2_Lmax3);
    R.Set(dataP, sizeR, this->GetTypeN());
    if(dataP!=NULL){
        delete[]dataP;
    }
    return R;
}
template<typename T> Array2D_shell<T> Array2D_shell<T>::GetSubArray_AsSuccOfExtRows(TDataShiftParams*DataShiftParam,      T*DefaultValParam,      int DfltRowL_00_11_Lmin2_Lmax3)const{
    T DefaultVal;
    if(DefaultValParam!=NULL){
        DefaultVal=(*(DefaultValParam));
    }
    return this->GetSubArray_AsSuccOfExtRows(DefaultVal, DataShiftParam, DfltRowL_00_11_Lmin2_Lmax3);
}
